// Isolation test (OS-12) — construct PopulationPartition with its declared inputs and nothing else, then
// exercise every public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { isUnknown, noSubject, type RecordHeight } from "../src/kernel/index.js";
import type { Unit } from "../src/catalog/index.js";
import { LineageReader, type Candidate } from "../src/facts/index.js";
import { RevisionLog, Samples } from "../src/condition/index.js";
import { ObservationLedger, score, type Score } from "../src/observation/index.js";
import { InvalidationLedger, InvalidationScope } from "../src/lineage/index.js";
import { PopulationPartition } from "../src/calibration/index.js";
import { inMemoryRecord } from "./catalog/in-memory-record.js";
import { factWorld } from "./support/fact-world.js";

const u = "u1" as Unit;

/** One sample at level easy: `a` committed (q 0.9), `b` passed over (q 0.3). */
function world() {
  const record = inMemoryRecord();
  const lineage = new LineageReader({ record });
  const invalidations = new InvalidationLedger({ record, scopes: new InvalidationScope({ lineage }), renderer: { present: () => undefined } });
  const w = factWorld({ currencies: ["c0"], invalidations, record });
  const c0 = w.order.least();
  const observations = new ObservationLedger({ record, components: ["q"] });
  const drawn = (n: number): Candidate => {
    const k = w.drawAt(u, c0, "x");
    observations.observe(k, { q: { value: score(n) as Score, author: "ENGINE" } }, "ENGINE", record.noise());
    return k;
  };
  const a = drawn(0.9);
  drawn(0.3);
  const k = w.commitments.commit(a, "HUMAN");
  const samples = new Samples({ candidates: w.candidates, draws: w.draws, revisions: new RevisionLog({ record }), lineage });
  const h: RecordHeight = record.noise();
  const parts: ConstructorParameters<typeof PopulationPartition>[0] = { lineage, samples, draws: w.draws, declarations: w.declarations, invalidations, observations };
  return { k, h, parts };
}

describe("PopulationPartition in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    const { parts } = world();
    for (const missing of Object.keys(parts)) expect(() => new PopulationPartition({ ...parts, [missing]: undefined } as never), missing).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    const { parts } = world();
    for (const slot of Object.keys(parts)) expect(() => new PopulationPartition({ ...parts, [slot]: {} } as never), slot).toThrow();
    // A slot of two operations needs both.
    expect(() => new PopulationPartition({ ...parts, lineage: { candidatesAsOf: () => [] } } as never)).toThrow();
    expect(() => new PopulationPartition({ ...parts, declarations: { levels: () => ["easy"] } } as never)).toThrow();
  });

  it("of answers, and differently when lineage differs", () => {
    const { h, parts } = world();
    const base = new PopulationPartition(parts).of("easy", "q").compute(h);
    expect(isUnknown(base)).toBe(false);
    expect(new PopulationPartition({ ...parts, lineage: { candidatesAsOf: () => [], commitmentsAsOf: () => [] } }).of("easy", "q").compute(h)).not.toEqual(base);
  });

  it("of answers differently when samples differs", () => {
    const { h, parts } = world();
    expect(new PopulationPartition({ ...parts, samples: { samplesFor: () => [] } }).of("easy", "q").compute(h)).not.toEqual(new PopulationPartition(parts).of("easy", "q").compute(h));
  });

  it("of answers differently when draws differs", () => {
    const { h, parts } = world();
    expect(new PopulationPartition({ ...parts, draws: { drawsAsOf: () => [] } }).of("easy", "q").compute(h)).not.toEqual(new PopulationPartition(parts).of("easy", "q").compute(h));
  });

  it("of answers differently when declarations differs", () => {
    const { h, parts } = world();
    const declarations = { levels: () => [], declarationAt: parts.declarations.declarationAt.bind(parts.declarations) };
    expect(new PopulationPartition({ ...parts, declarations }).of("easy", "q").compute(h)).not.toEqual(new PopulationPartition(parts).of("easy", "q").compute(h));
  });

  it("of answers differently when invalidations differs", () => {
    const { k, h, parts } = world();
    expect(new PopulationPartition({ ...parts, invalidations: { invalidatedAsOf: () => [k.at] } }).of("easy", "q").compute(h)).not.toEqual(new PopulationPartition(parts).of("easy", "q").compute(h));
  });

  it("of answers differently when observations differs", () => {
    const { h, parts } = world();
    expect(new PopulationPartition({ ...parts, observations: { observationOf: () => noSubject() } }).of("easy", "q").compute(h)).not.toEqual(new PopulationPartition(parts).of("easy", "q").compute(h));
  });
});
